import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"PointVLA: Injecting the 3D World into Vision-Language-Action Models","description":"","frontmatter":{"title":"PointVLA: Injecting the 3D World into Vision-Language-Action Models","arxiv":"2503.07511","date":"2025-03-10","authors":"Chengmeng Li, Junjie Wen, Yan Peng, Yaxin Peng, Feifei Feng, Yichen Zhu","categories":"cs.RO, cs.CV, cs.LG","topics":"通用具身智能, 视觉-语言-动作模型, 点云","outline":[2,2]},"headers":[],"relativePath":"papers/2503.07511.md","filePath":"papers/2503.07511.md","lastUpdated":null}'),e={name:"papers/2503.07511.md"};function l(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="pointvla-injecting-the-3d-world-into-vision-language-action-models" tabindex="-1">PointVLA: Injecting the 3D World into Vision-Language-Action Models <a class="header-anchor" href="#pointvla-injecting-the-3d-world-into-vision-language-action-models" aria-label="Permalink to &quot;PointVLA: Injecting the 3D World into Vision-Language-Action Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.07511" target="_blank" rel="noreferrer">2503.07511</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-10</td></tr><tr><td><strong>作者</strong></td><td>Chengmeng Li, Junjie Wen, Yan Peng, Yaxin Peng, Feifei Feng, Yichen Zhu</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>先用 skip-block 分析找出预训练动作专家里「跳过也不掉点」的层，只往这几层加性注入点云特征，从而不重训 2D VLA 就补上 3D 感知。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">命名与作者顺序</p><p>本站论文索引里该条目记作「3D/空间」，arXiv 真实标题是 <em>PointVLA</em>，非编号错误。另：abs 页的作者顺序与 HTML 全文不同（全文里 Yichen Zhu 排第二并标共同一作），frontmatter 按 本站体例 用 abs 页顺序。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 的能力来自 2D 视觉-语言预训练，代价是它只看得见像素。深度、尺度、&quot;这里有没有实体&quot;这些信息，在 RGB 图像里要么靠先验猜、要么靠训练集里恰好见过的桌面高度记住。这在演示分布内没问题，一旦桌面抬高 5 厘米、或者把物体换成屏幕上的一张照片，2D 策略会照着训练时的高度去抓一个不存在的东西。</p><p>直接的解法是拿 3D 数据重训，但这条路在成本上不成立：OpenVLA 用了 4k 小时开源数据，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 用了 10k 小时专有数据，<a href="/notes/papers/2503.06669">AgiBot World</a> 放出了百万条轨迹——这些资产全部是 2D 的。重训意味着把它们全部作废重来。本文要回答的问题因此非常具体：<strong>在不重训、不丢弃已有 2D 资产的前提下，怎么把点云接进一个已经训好的 VLA？</strong></p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>3D 机器人策略这条线已经有比较清楚的结论。DP3 表明外部相机的点云输入能显著提升对光照与物体属性变化的泛化；iDP3 改进了 3D 编码器并推到人形机器人上；3D-VLA 提出了统一 3D 任务的框架，但机器人控制部分只在仿真里验证，sim-to-real gap 明显。这些工作的共同前提是<strong>从头训一个 3D 策略</strong>。</p><p>另一条思路是把 3D 转成 token 塞进 LLM，像 LLaVA-3D 那样。本文明确否定了这条路，给的两条理由都成立：2D 像素与 3D 几何结构之间存在实质的域差；高质量 3D-文本配对数据远少于图文与纯文本语料，在小规模 3D 数据上微调 VLM 会得到很差的 3D 理解，而且会破坏原有的 2D 表示。</p><p>所以真正的空缺是：既不重训、也不把 3D 当作主模态，而是把它当成<strong>条件信号</strong>接进去。这个 framing 本身是本文最清晰的贡献。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>一步步倒推。既然 3D 数据的量级远小于 2D 预训练语料，那么任何让 3D 参与主干表示学习的做法都会过拟合。既然如此，3D 只能作为旁路条件。旁路条件加在哪？加在 VLM 里会污染视觉-语言对齐；加在动作专家里则只影响最后的动作解码，是更安全的位置。</p><p>那么加在动作专家的哪一层？这里作者借了一个来自图像生成与 LLM 的成熟观察：Transformer 的很多层是冗余的，推理时跳过部分层不会明显掉点。如果某一层跳过都不掉点，说明它当前承载的信息量低，那么把它的表示改掉、换成携带 3D 信息的表示，对原有能力的破坏就最小。这是一个&quot;找空位插队&quot;的直觉，逻辑链条完整、易于执行——但如后文所述，它中间有一个未被检验的跳跃。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把 3D 当作补充条件而不是新主模态，再把这个条件塞进模型里最&quot;闲&quot;的那几层。两句话讲完：新模态的数据量远不足以重塑主干表示，所以必须旁路接入；而 Transformer 里存在一批推理时可跳过的层，它们的表示对最终输出贡献低，因此是承接新模态而不损伤旧能力的最小代价入口。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>底座是 DexVLA：2B 的 Qwen2-VL 作 VLM，1B 的 ScaleDP（扩散策略变体，32 个 DiT block）作动作专家，原本经过三段训练（100 小时跨本体 → 本体专属 → 可选任务专属），全程只用 2D 输入。</p><p>以真机的&quot;传送带打包洗衣液&quot;任务为例：</p><ol><li><strong>2D 通路</strong>：头顶与两个腕部相机的 RGB 图像 + 语言指令进 Qwen2-VL，输出条件表示。</li><li><strong>3D 通路</strong>：RealSense L515 采点云，进一个简化的分层卷积编码器（上层卷积抽低级特征，下层抽高级场景表示，层间最大池化逐步降密度，最后把各层特征拼成统一嵌入）。作者明确说预训练 3D 编码器反而有害，这与 DP3/iDP3 的报告一致。</li><li><strong>注入器</strong>：先把点云嵌入的通道维对齐到动作专家的维度；因为动作嵌入的长度随 chunk size 变化，设计一个动作嵌入瓶颈做压缩与对齐；对选中的每个 block，用一个 MLP 适配器后<strong>加性</strong>注入。</li><li><strong>选层</strong>：见下节的 skip-block 分析，选中从第 11 块开始的 5 个连续块。</li><li><strong>训练</strong>：只训这 5 个注入块 + 为适配本体输出而调整的最后几层；动作专家其余部分冻结。chunk size 统一 50。</li></ol><p>关于 skip-block 分析本身：以 DexVLA 的叠衣服任务为案例，先逐个跳过单块，发现前 11 块任一被跳过都会显著掉点（具体表现是夹爪合不紧），从第 11 块起单块跳过可接受；再做连续多块跳过，发现从第 11 块起最多可连续跳过 5 块而不失败。于是把 3D 注入定在这 5 块上。</p><p><strong>这里有一处必须指出的自相矛盾</strong>：§3.2 论证方法有效性时写&quot;保持视觉-语言主干不动，从而确保 2D 视觉-文本嵌入被保留&quot;，而 §4.1 的实现细节明写&quot;我们把 VLM 设为可训练，因为模型需要学习新的语言指令&quot;。也就是说，论文最核心的设计承诺（不破坏 2D 表示）在实际实现中并未兑现。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文没有给出任何编号公式，方法层面的形式化程度很低。可以写下的只有注入操作本身：设动作专家第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">ℓ</span></span></span></span> 层的隐表示为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.888em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mtight">ℓ</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span></span></span></span>，点云编码器输出为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pc</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，注入为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.938em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.938em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mtight">ℓ</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">←</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0213em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.938em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mtight">ℓ</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pc</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">ℓ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">11</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">15</span><span class="mclose">}</span></span></span></span></span></p><p>值得说明的是加性注入的隐含含义。因为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是新初始化的、其余参数冻结，训练初期若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 输出接近零，则模型精确退化为原始 DexVLA。这给出了一个&quot;不会变差&quot;的初始化保证，是这类适配器设计的标准动机（与 ControlNet 的零卷积、LoRA 的零初始化同构）。但论文没有说明 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是否零初始化，因此这个保证只能算推测。</p><p>skip-block 分析背后隐含的判据同样值得形式化一下，因为它是全文方法论的支点。设跳过第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">ℓ</span></span></span></span> 层后的性能为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0385em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∖</span><span class="mord mtight">ℓ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span></span></span></span>，完整模型为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>，论文用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0385em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∖</span><span class="mord mtight">ℓ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 作为&quot;该层可承接新模态&quot;的判据。但这个量度量的是<strong>移除</strong>的代价，而注入关心的是<strong>改变</strong>的收益，两者之间没有推导关系：一个对输出影响小的层，既可能是&quot;有空位&quot;，也可能是&quot;信号传不出去&quot;。论文没有为这一步提供任何论证或对照实验。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>仿真（RoboTwin，Table 2）</strong>。14 个任务 × 20/50 条演示两档，3 个随机种子、每次评测 100 回合、报均值与标准差。对手是 DP3（纯点云）、DP3（点云+RGB）、DP。结论：PointVLA 在全部 28 个格子上都拿到最高均值。逐格看，优势幅度差别很大——Block Hammer Beat 20 条档从 47.7 提到 61.2，而 Dual Bottles Pick (Easy) 50 条档只从 67.3 提到 68.5、Empty Cup Place 50 条档从 71.3 到 73.5。另一个被作者点出的现象是给纯 3D 的 DP3 加 RGB 常常反而变差（例如 Diverse Bottles Pick 20 条档 13.3 → 0.7）。</p><p><strong>真机长时程（Table 1）</strong>。传送带上依次抓两袋洗衣液并封箱，分 5 个阶段计分，每方法 11 次试验。Octo 0.27、OpenVLA 0.36、DP 0.36、ScaleDP-1B 0.72、DexVLA 1.72、PointVLA 2.36。这张表的 Avg. Len. 可以逐项验算：DexVLA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord">/11</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">19/11</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.727</span></span></span></span>，PointVLA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">2</span><span class="mclose">)</span><span class="mord">/11</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">26/11</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.364</span></span></span></span>，与表中一致，说明这是&quot;每次试验最终停在第几阶段&quot;的直方图。</p><p><strong>少样本多任务（Fig. 5）</strong>、<strong>真假物体判别（§4.4）</strong>、<strong>高度适应（§4.5）</strong>：全部只有图与文字描述，无任何数值。</p><p>需要如实指出的问题按重要性排列。第一，<strong>Table 2 里没有 DexVLA 这一行</strong>——而论文自己说&quot;DexVLA 可以视为 PointVLA 去掉点云的消融&quot;。于是仿真部分实际上完全没有隔离点云的贡献，它只证明了&quot;一个 3B 的 VLA 打得过一个小扩散策略&quot;。第二，Table 2 的基线数值是<strong>从 RoboTwin 论文照抄</strong>的（作者明确注明），而 PointVLA 是自跑，种子与实现细节不可比；DP 在多个任务上恰好 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0</span></span></span></span> 是该基准已知的实现问题。第三，Table 1 只有 11 次试验，PointVLA 与 DexVLA 的 0.64 差距来自尾部两档（4/5 阶段 2+2 次 vs 1+0 次），实际就是约 3 次试验之差；而在第 2 阶段上 PointVLA 只有 1/11，远低于 DexVLA 的 5/11。第四，摘要称&quot;超过 OpenVLA、Diffusion Policy 与 DexVLA，在仿真与真机上都是&quot;，但 OpenVLA 与 DexVLA 根本没出现在仿真表里。第五，两个被作为核心卖点的能力（真假判别、高度适应）没有试验次数、没有成功率、没有基线数值，属于纯定性演示。第六，PointVLA 比所有 2D 基线多一路 L515 传感器，而它自己相对 DP/ScaleDP 还多了 DexVLA 阶段一的 100 小时跨本体预训练——模态与预训练规模两个变量始终绑在一起。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：VLA 的 2D 资产太贵、3D 数据太少，所以正确的接法是把点云当条件旁路接入而非当新主模态重训。PointVLA 的做法是冻结动作专家，用 skip-block 分析选出 5 个&quot;跳过也不掉点&quot;的层，往里加性注入点云特征，只训这 5 个注入块。RoboTwin 上 28 个格子全胜，真机长时程比 DexVLA 高 0.64 个阶段，并演示了真假物体判别与桌面高度适应两项 2D 模型做不到的能力。但仿真表里缺 DexVLA 这一行，两项定性能力没有任何数字，而&quot;选层&quot;这条方法论主线<strong>从未被消融</strong>——论文没有比较过注入到别的层会怎样。加上 §3.2 与 §4.1 关于 VLM 是否冻结的直接矛盾，方法的真实作用机制仍是开放的。</p><p><strong>三句话版</strong>：问题选得很准，&quot;把新模态接进冻结的旧模型&quot;是 VLA 时代的真问题。工程实现干净、代价低、真机演示有说服力。但实验设计没有把&quot;有没有点云&quot;&quot;注入到哪里&quot;&quot;预训练多少&quot;这三件事分开，因此看不出方法里哪一部分在起作用。</p><p><strong>一句话版</strong>：把 3D 当条件而不是当主模态是对的；但&quot;往最闲的层里插&quot;这条规则，全文没有做过哪怕一次对照实验。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>&quot;跳过不掉点的层&quot;就是&quot;注入新模态最合适的层&quot;</strong>。</p><p>这条假设承载了全文的方法论novelty——摘要、引言、§3.3 都把 skip-block 分析当作核心贡献。但它中间有一个逻辑跳跃：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0385em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∖</span><span class="mord mtight">ℓ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 说明第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">ℓ</span></span></span></span> 层当前输出的<strong>增量</strong>对结果影响小，它有两种截然相反的解释。解释一（论文采用的）：这层是冗余的，有空位，改它代价低。解释二：这层处在残差流中信息已经饱和的位置，或者其后的层对该位置的扰动不敏感，因此从这里注入的信号同样<strong>传不到输出</strong>。第二种解释下，注入 3D 特征的效果会趋近于零，而真正带来增益的是别的因素（多的那一路传感器让点云编码器直接学到了任务相关特征？可训练的 VLM？还是仅仅多了 5 个块的可训练参数？）。</p><p>论文对此没有任何证据。它只做了&quot;跳过哪些层不掉点&quot;的分析（而且只在<strong>叠衣服一个任务</strong>上做），从未做&quot;注入到不同层组&quot;的下游对照。这意味着 §3.3 那整节分析在因果上是悬空的：它决定了超参，却没有被验证过这个超参重要。若这条假设不成立，PointVLA 会退化成&quot;一个加了点云分支并多训了一些参数的 DexVLA&quot;，方法叙事需要整体改写。</p><p>顺带一提，这条假设的脆弱性还被前面那处自相矛盾放大了：既然 VLM 实际上是可训练的，那么&quot;最小化对预训练表示的扰动&quot;这个整体动机本身就没有被严格执行，选层的收益即使存在也很可能被 VLM 的更新淹没。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只需要仿真，不需要真机。</p><ul><li><strong>数据/环境</strong>：RoboTwin，选 3 个中等难度任务（Block Hammer Beat、Container Place、Empty Cup Place），20 条演示档，3 个种子 × 100 次评测（与论文协议一致）。</li><li><strong>实现</strong>：取公开的 DexVLA 权重，按 §5 实现点云注入器，训练四个变体：(a) 注入到 block 11–15（论文配置）；(b) 注入到 block 0–4（论文判定为&quot;关键&quot;的层）；(c) 注入到随机选的 5 个 block；(d) 不注入点云的 DexVLA 对照（即仅微调最后几层）。所有变体的可训练参数量、数据、步数、随机种子严格对齐。</li><li><strong>测量</strong>：四个变体的成功率均值与标准差。</li><li><strong>判据</strong>：若 (a)(b)(c) 三者的差距落在种子标准差之内，则 skip-block 分析对结果没有贡献，方法的实际有效成分是&quot;加了点云分支&quot;，论文的核心方法论主张不成立。若 (d) 与 (a) 差距很小，则连点云本身在仿真里的贡献都存疑（这一格恰恰是论文缺的那一行）。若 (a) 明显优于 (b)(c) 且 (d) 明显更差，则论文两条主张同时被证实——这是最省力的判决性实验。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释一：两项旗舰能力可能只需要一个标量。</strong> 真假物体判别与桌面高度适应，本质上要的信息分别是&quot;这个位置有没有实体&quot;和&quot;支撑面在哪个高度&quot;。判决实验：把点云编码器整体换成一个 8 维的深度直方图（甚至 1 维的工作区平均高度），用同样的注入方式接入，重跑这两个演示。如果这两项能力照样出现，那么它们证明的只是&quot;有任何深度信号即可&quot;，与点云编码器、与 skip-block 选层、与整套注入架构都无关。考虑到这两项恰好是论文用来论证&quot;3D 世界知识&quot;的全部定性证据，这个反例的杀伤力很大。</p><p><strong>替代解释二：真假判别可能是传感器伪影而非 3D 理解。</strong> 实验用 RealSense L515 采点云，而 L515 是 LiDAR 相机；在自发光的 LCD 屏幕上，LiDAR 的回波通常是缺失或错误的。也就是说 PointVLA &quot;看到那里是空的&quot;可能字面意义上是传感器在屏幕上没有返回有效点，而不是模型推理出&quot;这是一张平面图像&quot;。干净的判决实验：把屏幕换成一张<strong>平铺在传送带上的哑光打印海报</strong>（同样是平面、同样在 2D 视角下像洗衣液，但对 LiDAR 是正常漫反射面），再测一次。如果换成打印件后 PointVLA 也去抓了，那么&quot;3D 世界知识缓解物体幻觉&quot;这个结论就要限定为&quot;该深度传感器恰好在屏幕上失效&quot;。</p><p><strong>可预测的失败条件</strong>：论文的高度适应实验把泡沫层从 3 mm 加到 52 mm 并成功。但注入的是全局点云嵌入而非结构化的几何量，所以可以预期它在<strong>多物体不同高度</strong>、或<strong>桌面倾斜</strong>、或<strong>点云与 RGB 未严格标定</strong>的情况下退化——这三种情况在四个真机任务里一个都没出现。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>本文真正提出的问题比它的解法更有价值：当模型资产已经沉没在某个模态上时，如何把新模态<strong>嫁接</strong>上去。目前的答案是一次性的、手工的、单任务上做的层选择。</p><p><strong>新的 framing</strong>：把&quot;新模态该从哪里进入冻结主干&quot;从一个超参调优问题，升级为一个<strong>可测量、可预测的模型内部属性</strong>。也就是说，我们想要的不是&quot;在这个模型上跳过第 11–15 层没事&quot;，而是一个只需前向传播就能算出的量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϕ</span><span class="mopen">(</span><span class="mord">ℓ</span><span class="mclose">)</span></span></span></span>，它能预测从第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">ℓ</span></span></span></span> 层注入的下游收益，从而对任意新模型、新模态直接给出接入方案，不需要每次都重做一遍 skip 实验。</p><p>(a) <strong>驱动它的局限</strong>：skip-block 分析在叠衣服一个任务上做出、被推广到 14 个仿真任务与两种真机本体，且从未被下游对照验证；每换一个底座模型就要重做，成本随模型规模线性增长。(b) <strong>可借鉴的相邻领域工具</strong>：持续学习里用 Fisher 信息矩阵度量参数重要性的成熟做法（EWC 一族）；参数高效迁移里关于适配器放置位置的系统研究（AdapterDrop、LoRA 层位分析）；以及多任务学习里的梯度冲突度量（逐层计算旧任务梯度与新模态梯度的余弦相似度）。这三者给出的都是&quot;改这里代价多大&quot;的量，而本文缺的恰恰是&quot;从这里注入收益多大&quot;，两者可以配成一对。(c) <strong>第一个实验长什么样</strong>：在冻结的动作专家上，对每个 block 计算两个量——预训练任务上的逐层 Fisher 信息 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord">ℓ</span><span class="mclose">)</span></span></span></span>，以及旧任务梯度与点云分支梯度的逐层余弦 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">c</span><span class="mopen">(</span><span class="mord">ℓ</span><span class="mclose">)</span></span></span></span>；然后按 §10 的协议逐层实测注入收益 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mopen">(</span><span class="mord">ℓ</span><span class="mclose">)</span></span></span></span>。核心问题是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 的相关性符号。如果 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span> 呈<strong>正</strong>相关（即应该往重要的层注入），那就直接推翻本文的选层规则，并给出一条可迁移的新准则；如果呈负相关，本文的直觉获得了它现在缺的那个定量支撑。无论哪个方向，这都是一个比&quot;再多做一个模态&quot;更有价值的结果。</p>',52)])])}const u=a(e,[["render",l]]);export{h as __pageData,u as default};
